  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Bicuculline, a phthalideisoquinoline alkaloid sharing the same core scaffold as noscapine, penetrated the brain in a dose-dependent manner in rats, directly supporting meaningful CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tetrahydroberberine, a related berberine-family alkaloid, was detected in rat CSF after administration, demonstrating passage across the BBB and supporting CNS access for noscapine-like alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Allocryptopine, another related alkaloid, was detected in rat CSF, providing independent evidence that this alkaloid family can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Isocorydine effectively crossed the BBB in rats with considerable brain levels within 10 minutes, supporting the CNS-penetrant profile of this alkaloid family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine reached brain concentrations nearly equal to plasma in rats, providing additional support that this alkaloid class achieves meaningful brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Noscapine is a phthalideisoquinoline alkaloid closely related to bicuculline and other CNS-penetrant alkaloids; direct brain and CSF evidence in rats for these analogs supports meaningful BBB access, and no evidence indicates restricted penetration.",
  "evidence_gaps": [
    "No direct noscapine-specific brain/plasma or CSF quantification is present in the provided records.",
    "No glioma/tumor-bearing model data are provided; tumor-associated BBB changes are not directly assessed.",
    "Efflux transporter involvement for noscapine is not directly measured in these records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

